//! Asserts the COMMITTED `fixtures/audio/silence.wav` (generated by
//! `examples/gen_silence.rs`, not regenerated by this test) has the
//! measured-MacBook-floor stats the plan requires: per-250ms-window RMS
//! median ≈ 0.0061, p90 ≈ 0.0104, max ≤ 0.0156, all below
//! `voxis_core::guard`'s `SILENCE_RMS` (0.02).

use voxis_fake_stt::silence_gen::{windowed_peak_rms, SilenceGenParams};

fn read_wav_as_f32(path: &std::path::Path) -> Vec<f32> {
    let mut reader = hound::WavReader::open(path).unwrap_or_else(|e| panic!("opening {}: {e}", path.display()));
    reader.samples::<i16>().map(|s| s.unwrap() as f32 / 32768.0).collect()
}

#[test]
fn silence_wav_is_16khz_mono_seventeen_seconds() {
    let manifest_dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR"));
    let path = manifest_dir.join("../../fixtures/audio/silence.wav");
    let reader = hound::WavReader::open(&path).unwrap_or_else(|e| {
        panic!("fixtures/audio/silence.wav must exist (run `cargo run -p voxis-fake-stt --example gen_silence`): {e}")
    });
    let spec = reader.spec();

    assert_eq!(spec.channels, 1, "silence.wav must be mono");
    assert_eq!(spec.sample_rate, 16_000, "silence.wav must be 16 kHz");

    let duration_ms = (reader.duration() as u64 * 1000) / spec.sample_rate as u64;
    assert!((duration_ms as i64 - 17_000).abs() <= 50, "silence.wav must be ~17s, got {duration_ms}ms");
}

#[test]
fn silence_wav_per_window_rms_matches_the_measured_mac_book_floor() {
    let manifest_dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR"));
    let path = manifest_dir.join("../../fixtures/audio/silence.wav");
    let samples = read_wav_as_f32(&path);
    let params = SilenceGenParams::default();

    let windows = windowed_peak_rms(&samples, params.sample_rate, params.window_ms, params.sub_chunk_ms);
    let mut sorted = windows.clone();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap());
    let median = sorted[sorted.len() / 2];
    let p90 = sorted[(sorted.len() as f64 * 0.9) as usize];
    let max = *sorted.last().unwrap();

    // `voxis_core::guard::SILENCE_RMS` is 0.02 -- the hard requirement is
    // "every window reads as silent"; the median/p90 checks below are a
    // generous tolerance band around the specific measured numbers, not
    // an exact-match requirement (the PRNG's per-window sampling variance
    // means no single run lands exactly on the target).
    assert!(max < 0.02, "every 250ms window must read as silent under SILENCE_RMS=0.02, got max={max}");
    assert!(max <= 0.0156 + 1e-6, "max window RMS {max} must not exceed 0.0156");
    assert!((median - 0.0061).abs() / 0.0061 < 0.4, "median {median} too far from the measured 0.0061");
    assert!((p90 - 0.0104).abs() / 0.0104 < 0.4, "p90 {p90} too far from the measured 0.0104");
}
